node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { canonical } from './dist/framework/core/index.js';
import { defineIR, differential, differentialSpec, runDifferential } from './dist/framework/contracts/index.js';
import { createIRArtifact, defineAdapter, openIR } from './dist/framework/ir/index.js';
import { applyPass, definePass } from './dist/framework/passes/index.js';
import { AnalysisManager } from './dist/framework/contracts/index.js';
const data = [1, 0, 0, 0, ...Array(4).fill(2 ** -24), .25];
const sum = xs => xs.reduce((a, b) => Math.fround(a + b), 0);
const linear = sum(data), split = sum([sum(data.slice(0, 4)), sum(data.slice(4, 8)), sum(data.slice(8))]);
const ref = data.reduce((a, b) => a + b, 0);
const ir = defineIR({ id: 'probe', version: '1', description: 'probe', validate(v) { assert.equal(typeof v, 'number'); }});
const entity = value => ({ id: 'e', kind: 'value', attributes: { value } });
const adapter = defineAdapter({ id: 'probe', version: '1', kind: ir.id, schemaVersion: ir.version,
  description: 'probe', validate: ir.validate, relationKinds: {}, entities: v => [entity(v)],
  resolve: (v, id) => id === 'e' ? entity(v) : undefined, describe: () => ({}), relations: () => [] });
const origin = createIRArtifact(adapter, 'probe', linear);
const candidate = createIRArtifact(adapter, 'probe', split);
assert.equal(openIR(origin, adapter).graph().entities.length, 1);
const pass = definePass({ id: 'probe', version: '1', description: 'probe', ir, adapter,
  writes: { entities: ['value'], relations: [] }, run: () => ({ native: split }) });
const pending = applyPass(pass, origin, { manager: new AnalysisManager() });
assert.ok(pending instanceof Promise);
assert.equal((await pending).artifact.revision, candidate.revision);
for (const [id, compare] of [
  ['exact', (a,b) => Object.is(a,b)],
  ['tolerance', (_,b) => Math.abs(b - ref) <= 2e-6 + 2e-5 * Math.abs(ref)],
]) {
  const inv = differential({ id, version: '1', description: id, inputs: { origin: ir, candidate: ir },
    baseline: 'origin', subject: 'candidate', count: 1, cases: () => [null], run: (_, a) => a.value, compare });
  assert.equal(runDifferential(differentialSpec(inv), { origin, candidate }).status, id === 'exact' ? 'disagree' : 'agree');
}
const bit = n => new Uint32Array(new Float32Array([n]).buffer)[0].toString(16);
assert.equal(bit(-0), '80000000');
assert.equal(canonical(-0), canonical(0));
console.log({ linear, split, ref, linearBits: bit(linear), splitBits: bit(split), badTail: sum([sum(data.slice(0,4)),sum(data.slice(4,8))]) });
NODE

node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { canonical } from './dist/framework/core/index.js';
import { AnalysisManager, defineIR, differential, differentialSpec, runDifferential } from './dist/framework/contracts/index.js';
import { createIRArtifact, defineAdapter, openIR } from './dist/framework/ir/index.js';
import { applyPass, definePass } from './dist/framework/passes/index.js';
const src = [1,0,0,0,...Array(4).fill(2**-24),0.25];
const sum = xs => xs.reduce((a,b) => Math.fround(a+b),0);
const partials = [sum(src.slice(0,4)),sum(src.slice(4,8)),sum(src.slice(8))];
const linear = sum(src), split = sum(partials), ref = src.reduce((a,b) => a+b,0);
const ir = defineIR({ id:'probe',version:'1',description:'probe',validate(v){assert.equal(typeof v,'number');} });
const entity = value => ({id:'e',kind:'value',attributes:{value}});
const adapter = defineAdapter({id:'probe',version:'1',kind:ir.id,schemaVersion:ir.version,
  description:'probe',validate:ir.validate,relationKinds:{},entities:v=>[entity(v)],resolve:v=>entity(v),
  describe:()=>({}),relations:()=>[],rebuild:v=>v});
const origin = createIRArtifact(adapter,'probe',linear), candidate = createIRArtifact(adapter,'probe',split);
assert.equal(openIR(origin,adapter).graph().entities.length,1);
const pass = definePass({id:'probe',version:'1',description:'probe',ir,adapter,
  writes:{entities:['value'],relations:[]}, run:()=>({native:split})});
const pending = applyPass(pass,origin,{manager:new AnalysisManager()});
assert.ok(pending instanceof Promise);
assert.equal((await pending).artifact.revision,candidate.revision);
for(const [id,compare,status] of [['exact',Object.is,'disagree'],
  ['tolerance',(_,b)=>Math.abs(b-ref)<=2e-6+2e-5*Math.abs(ref),'agree']]){
  const inv = differential({id,version:'1',description:id,inputs:{origin:ir,candidate:ir},
    baseline:'origin',subject:'candidate',count:1,cases:()=>[null],run:(_,a)=>a.value,compare});
  assert.equal(runDifferential(differentialSpec(inv),{origin,candidate}).status,status);
}
const bit = n => new Uint32Array(new Float32Array([n]).buffer)[0].toString(16);
assert.equal(bit(-0),'80000000');
assert.equal(canonical(-0),canonical(0));
console.log({linear,split,ref,linearBits:bit(linear),splitBits:bit(split),badTail:sum(partials.slice(0,2))});
NODE
